const vals = wb.getRange('Sheet1!B1:B12').getValues().map(r => r[0]);
const lastIdx = new Map(); vals.forEach((v,i)=>lastIdx.set(v,i));
const keep = new Set(lastIdx.values());
const removed = [];
for (let i = vals.length-1; i>=0; i--) { if (!keep.has(i)) { wb.getRange(`Sheet1!${i+1}:${i+1}`).delete(); removed.push(i+1); } }
log('removed', removed.join(','), 'kept', [...keep].map(i=>i+1).join(','));
